import { accountApi, discoverAccountConfig } from './account.js';
import { toDataURL } from './vendor/qr.js';
import { saveMinorityAuthIntent } from './minority-auth-intent.js';

const app = document.querySelector('#minority-topic-app');
const query = new URLSearchParams(location.search);
const roomIdFromUrl = query.get('room');
const inviteFromUrl = query.get('invite');
const storageKey = (id) => `mingle.minority.room:${id}`;
const state = { roomId: roomIdFromUrl, invite: inviteFromUrl, token: '', data: null, host: query.get('host') === '1' || query.get('create') === '1' || Boolean(query.get('venue')), terminal: false, busy: false, error: '', name: '', revealed: false, viewed: false, voted: false, pollDelay: 1000, pollTimer: 0, requestEpoch: 0, lastViewKey: '' };
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[char]));
const joinKey = (id) => `mingle.minority.join:${id || 'pending'}`;
let memoryJoinSecret = '';
function newJoinSecret() { const bytes = new Uint8Array(32); crypto.getRandomValues(bytes); return btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, ''); }
function readJoinSecret() { if (memoryJoinSecret) return memoryJoinSecret; try { const value = sessionStorage.getItem(joinKey(state.roomId)); if (/^[A-Za-z0-9_-]{43}$/.test(value || '')) return memoryJoinSecret = value; } catch {} return memoryJoinSecret = newJoinSecret(); }
function saveJoinSecret(secret) { memoryJoinSecret = secret; try { sessionStorage.setItem(joinKey(state.roomId), secret); } catch {} }
function clearJoinSecret() { memoryJoinSecret = ''; try { sessionStorage.removeItem(joinKey(state.roomId)); } catch {} }
function shell(content) { app.innerHTML = `<div class="minority-brand"><img src="/assets/mingle-cards-masthead.png" alt="Mingle.Cards"><a class="group-back" href="/">トップへ戻る</a></div>${content}`; }
function error() { return state.error ? `<p class="minority-error" role="alert">${esc(state.error)}</p>` : ''; }
function saveCredential() { if (!state.roomId || !state.token) return; try { sessionStorage.setItem(storageKey(state.roomId), JSON.stringify({ roomId: state.roomId, invite: state.invite, token: state.token, host: state.host === true })); } catch {} }
function restoreCredential() { if (!state.roomId || state.token) return; try { const value = JSON.parse(sessionStorage.getItem(storageKey(state.roomId)) || 'null'); if (value?.roomId === state.roomId && typeof value.token === 'string' && value.token) { state.invite ||= value.invite || ''; state.token = value.token; state.host = value.host === true || state.host; } } catch {} }
function clearCredential() { if (!state.roomId) return; try { sessionStorage.removeItem(storageKey(state.roomId)); } catch {} state.token = ''; }
function createView() { shell(`<section class="minority-card"><h1>QRで集まって遊ぶ</h1><p class="minority-note">1人だけ違うお題が配られます。言葉を直接言わずにヒントを話し、最後に投票で当てます。3〜8人・全6ラウンドです。</p><p class="minority-note">代表者がルームを作り、参加者はQRまたはURLから参加します。</p><form class="minority-form" data-create><label>代表者の呼び名<input name="name" required maxlength="20" autocomplete="nickname" value="${esc(state.name)}"></label><button class="primary-button" type="submit" ${state.busy ? 'disabled' : ''}>${state.busy ? '作成中…' : 'ルームを作る'}</button>${error()}${state.error.includes('ログインが必要') ? '<a class="secondary-button" data-login-return href="/?minorityAuth=1">ログインしてルームを作る</a>' : ''}</form></section>`); }
function joinView() { shell(`<section class="minority-card"><h1>ルームに参加</h1><p class="minority-note">1人だけ違うお題が配られます。言葉を直接言わずにヒントを話し、最後に投票で当てます。</p><p class="minority-note">呼び名を入力して参加してください。</p><form class="minority-form" data-join><label>呼び名<input name="name" required maxlength="20" autocomplete="nickname" value="${esc(state.name)}"></label><button class="primary-button" type="submit" ${state.busy ? 'disabled' : ''}>${state.busy ? '参加中…' : '参加する'}</button>${error()}</form></section>`); }
function qrBlock() { const url = `${location.origin}/minority-room.html?room=${encodeURIComponent(state.roomId)}&invite=${encodeURIComponent(state.invite || '')}`; return `<div class="group-qr"><img data-qr alt="参加用QRコード"><label>参加用URL<input readonly value="${esc(url)}" aria-label="参加用URL"></label><button class="secondary-button" type="button" data-copy>URLをコピー</button><small>QRが表示できないときはURLを渡してください</small></div>`; }
function view(data) {
  const room = data.room; const game = data.minority || data; const members = room.members || []; const host = data.host === true; const phase = game.phase || 'lobby';
  const viewKey = JSON.stringify([room.status, room.revision, phase, game.round, game.confirmed, game.votedCount, game.memberHasVoted, game.outcome, state.revealed, state.voted]);
  if (viewKey === state.lastViewKey && !state.error) return;
  state.lastViewKey = viewKey;
  let body = `<p class="minority-progress">参加者 ${members.length} / 8人${game.round ? `・第${game.round}ラウンド / 6` : ''}</p><ul class="minority-list">${members.map((m) => `<li>${esc(m.name)}${m.role === 'host' ? '（代表者）' : ''}</li>`).join('')}</ul>`;
  if (room.status === 'ended' || phase === 'ended') body += '<div class="minority-result">このゲームは終了しました。</div>';
  else if (phase === 'lobby') body += host ? `<button class="primary-button" data-act="start" ${state.busy || members.length < 3 || members.length > 8 ? 'disabled' : ''}>${state.busy ? '開始中…' : '開始する'}</button><p class="minority-note">${members.length < 3 ? '3人以上で開始できます。' : ''}</p>${qrBlock()}` : '<p class="minority-note">代表者が開始するまでお待ちください。</p>';
  else if (phase === 'confirm') { const word = game.myWord || ''; body += `<h1>お題を確認</h1><p class="minority-note">${game.confirmed ? '確認済みです。お題は伏せています。必要なら本人だけで再表示できます。' : '本人だけで確認してください。'}</p>${state.revealed ? `<p class="minority-word">${esc(word)}</p><button class="primary-button" data-hide>確認して伏せる</button>` : `<p class="minority-word is-hidden">伏せています</p>${!game.confirmed && state.viewed ? '<button class="primary-button" data-act="confirm">確認済み・次へ</button>' : '<button class="primary-button" data-reveal>お題を見る</button>'}`}`; }
  else if (phase === 'talk') body += `<h1>ヒントタイム</h1><p class="minority-note">お題の言葉そのものは言わずに、口頭でヒントを出し合いましょう。</p>${host ? `<button class="primary-button" data-act="vote_open" ${state.busy ? 'disabled' : ''}>投票を始める</button>` : '<p class="minority-note">代表者が投票を始めます。</p>'}`;
  else if (phase === 'vote') { const submitted = state.voted || game.memberHasVoted === true; const choices = submitted ? '' : members.filter((m) => m.id !== data.member?.id).map((m) => `<button class="secondary-button" data-target="${esc(m.id)}" ${state.busy ? 'disabled' : ''}>${esc(m.name)}に投票</button>`).join(''); body += `<h1>秘密投票</h1><p class="minority-note">${submitted ? '投票しました。ほかの人を待っています。' : '自分以外から1人を選んでください。'}</p><p class="minority-progress">投票済み：${game.votedCount ?? '—'} / ${game.memberCount ?? members.length}人</p><div class="minority-actions">${choices}</div>`; }
  else if (phase === 'result') { const tally = Object.entries(game.tally || {}).map(([id, count]) => `${esc(members.find((m) => m.id === id)?.name || id)}：${count}票`).join(' / '); const outcome = game.outcome === 'draw' ? '引き分け' : game.outcome === 'majority_win' ? '多数派の勝ち' : '少数派の勝ち'; const minorityName = members.find((m) => m.id === game.minorityMemberId)?.name || game.minorityMemberId || '—'; body += `<h1>${outcome}</h1><div class="minority-result">少数派：<strong>${esc(minorityName)}</strong><br>多数派のお題：${esc(game.majorityWord || '—')}<br>少数派のお題：${esc(game.minorityWord || '—')}<br>${tally}</div>${host && Number(game.round || 0) < Number(game.maxRounds || 6) ? '<button class="primary-button" data-act="next_round">次のラウンド</button>' : ''}${host ? '<button class="secondary-button" data-act="finish">ゲームを終了</button>' : ''}`; }
  if (host && !['lobby', 'result', 'ended'].includes(phase)) body += '<button class="secondary-button" data-act="finish">ゲームを終了</button>';
  shell(`<section class="minority-card"><h1>ひとりだけ違うお題</h1>${body}${error()}</section>`);
  if (phase === 'lobby' && host) { const url = `${location.origin}/minority-room.html?room=${encodeURIComponent(state.roomId)}&invite=${encodeURIComponent(state.invite || '')}`; const qr = app.querySelector('[data-qr]'); toDataURL(url, { margin: 4, width: 180 }).then((value) => { if (qr?.isConnected) qr.src = value; }).catch(() => { if (qr?.isConnected) qr.alt = 'QRを表示できません。下のURLをご利用ください'; }); app.querySelector('[data-copy]')?.addEventListener('click', async () => { try { await navigator.clipboard.writeText(url); state.error = 'URLをコピーしました。'; renderCurrent(); } catch { state.error = 'コピーできませんでした。URLを長押ししてコピーしてください。'; renderCurrent(); } }); }
}
function renderCurrent() { state.lastViewKey = ''; if (state.data) view(state.data); else if (state.terminal) shell(`<section class="minority-card"><h1>ルームを表示できません</h1>${error()}<a class="primary-button" href="/minority-room.html?create=1">新しいルームを作る</a></section>`); else state.host ? createView() : joinView(); }
async function load() { if (!state.roomId || !state.token || state.busy) return; const epoch = state.requestEpoch; try { const beforeRound = (state.data?.minority || state.data)?.round; const data = await accountApi.groupState(state.roomId, state.token); if (epoch !== state.requestEpoch) return; state.data = data; state.host = data.host === true; state.error = ''; state.terminal = false; state.pollDelay = 1000; const nextRound = (data.minority || data)?.round; if (beforeRound !== nextRound) { state.revealed = false; state.viewed = false; state.voted = false; } view(data); } catch (e) { if (epoch !== state.requestEpoch) return; const status = Number(e?.status); if ([401, 403].includes(status)) { clearCredential(); state.error = '参加資格を確認できません。もう一度参加してください。'; state.data = null; joinView(); return; } if ([404, 410].includes(status)) { state.error = 'このルームは終了または期限切れです。'; state.data = null; state.terminal = true; renderCurrent(); return; } state.error = '通信できません。接続を確認して再試行してください。'; renderCurrent(); state.pollDelay = Math.min(15000, state.pollDelay * 2); } schedulePoll(); }
function schedulePoll() { clearTimeout(state.pollTimer); const phase = (state.data?.minority || state.data)?.phase; if (!state.data || state.busy || document.hidden || !navigator.onLine || phase === 'ended' || state.data.room?.status === 'ended') return; state.pollTimer = setTimeout(load, state.pollDelay); }
async function act(action, targetId = '') { if (state.busy || !state.data) return; state.busy = true; state.requestEpoch += 1; renderCurrent(); let stale = false; try { const game = state.data.minority || state.data; const result = await accountApi.minorityAction(state.roomId, state.token, action, state.data.room.revision, targetId, game.round); const nextGame = result.minority || result; if (nextGame.round !== game.round) { state.revealed = false; state.viewed = false; state.voted = false; } state.data = result; state.host = result.host === true; state.voted = action === 'vote' ? true : state.voted; state.revealed = false; if (action === 'confirm') state.viewed = false; state.error = ''; saveCredential(); } catch (e) { if (e?.status === 409) { state.error = '進行が更新されています。最新状態を読み込みます。'; stale = true; } else state.error = e?.message === 'MINORITY_SELF_VOTE' ? '自分には投票できません。' : '操作を反映できませんでした。再試行してください。'; } finally { state.busy = false; renderCurrent(); if (stale) await load(); else schedulePoll(); } }
app.addEventListener('submit', async (event) => { event.preventDefault(); if (state.busy) return; const form = event.target; state.name = String(new FormData(form).get('name') || '').trim(); state.busy = true; renderCurrent(); try { if (form.matches('[data-create]')) { const result = await accountApi.createMinorityRoom(state.name, query.get('venue') || ''); state.roomId = result.room.id; state.invite = result.inviteToken; state.token = result.memberToken; state.host = true; saveCredential(); history.replaceState({}, '', `/minority-room.html?room=${encodeURIComponent(state.roomId)}&invite=${encodeURIComponent(state.invite)}&host=1`); state.data = result; } else { const memberSecret = readJoinSecret(); saveJoinSecret(memberSecret); const result = await accountApi.joinGroupRoom(state.roomId, state.invite, state.name, false, memberSecret, false); state.token = result.memberToken; state.host = false; clearJoinSecret(); saveCredential(); state.data = result; } state.error = ''; } catch (e) { if (form.matches('[data-create]') && (Number(e?.status) === 401 || e?.message === 'UNAUTHENTICATED')) { saveMinorityAuthIntent({ venueToken: query.get('venue') || '', name: state.name }); location.assign('/?minorityAuth=1'); return; } state.error = Number(e?.status) === 401 || e?.message === 'UNAUTHENTICATED' ? 'ルーム作成にはログインが必要です。' : '参加できませんでした。入力と招待URLを確認してください.'; } finally { state.busy = false; renderCurrent(); schedulePoll(); } });
app.addEventListener('click', (event) => { const button = event.target.closest('button'); if (!button) return; if (button.matches('[data-reveal]')) { state.revealed = true; state.viewed = true; renderCurrent(); return; } if (button.matches('[data-hide]')) { const game = state.data?.minority || state.data; if (!game?.confirmed) { state.revealed = false; act('confirm'); } else { state.revealed = false; renderCurrent(); } return; } if (button.dataset.act) { act(button.dataset.act); return; } if (button.dataset.target) { act('vote', button.dataset.target); } });
document.addEventListener('visibilitychange', () => { if (!document.hidden) { load(); schedulePoll(); } else clearTimeout(state.pollTimer); });
window.addEventListener('online', () => { load(); schedulePoll(); });
await discoverAccountConfig(); restoreCredential();
if (state.roomId && state.token) load(); else if (state.roomId && !state.host) { try { await accountApi.previewGroupRoom(state.roomId, state.invite); joinView(); } catch { state.error = 'このルームは見つかりません。'; joinView(); } } else if (state.host) createView(); else shell('<section class="minority-card"><h1>参加リンクがありません</h1><a class="primary-button" href="/">トップへ戻る</a></section>');
